import{_ as a,c as i,o as t,a2 as n}from"./chunks/framework.PGES7OoM.js";const k=JSON.parse('{"title":"getTransactionHistory","description":"Merge local actions and chain fallbacks using account-wide ordering and deduplication.","frontmatter":{"editLink":false,"rawMarkdown":"# getTransactionHistory\\n\\nMerge local actions and chain fallbacks using account-wide ordering and deduplication.\\n\\n## Import\\n\\n```ts\\nimport { getTransactionHistory } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst history = await getTransactionHistory({\\n  accountId,\\n  networkSlug,\\n  config,\\n});\\n```\\n\\n## Signature\\n\\n```ts\\nfunction getTransactionHistory(parameters?: GetTransactionHistoryParameters): Promise<TransactionHistoryItem[]>\\n```\\n\\n## Returns\\n\\n`Promise<TransactionHistoryItem[]>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nThe account whose transaction records should be returned. Defaults to the active account.\\n\\n```ts\\nconst result = await getTransactionHistory({\\n  accountId, // [!code focus]\\n});\\n```\\n\\n### `networkSlug`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nLimit results to this network slug.\\n\\n```ts\\nconst result = await getTransactionHistory({\\n  networkSlug, // [!code focus]\\n});\\n```\\n\\n### `token`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nVault token id as a decimal string.\\n\\n```ts\\nconst result = await getTransactionHistory({\\n  token, // [!code focus]\\n});\\n```\\n\\n### `limit`\\n\\n- **Type:** `number`\\n- **Required:** no\\n\\nThe maximum number of transaction records to return.\\n\\n```ts\\nconst result = await getTransactionHistory({\\n  limit, // [!code focus]\\n});\\n```\\n\\n### `ids`\\n\\n- **Type:** `readonly string[]`\\n- **Required:** no\\n\\nHydrate selected stable activity IDs without reading every history record or attempt.\\n\\n```ts\\nconst result = await getTransactionHistory({\\n  ids, // [!code focus]\\n});\\n```\\n\\n### `signal`\\n\\n- **Type:** `AbortSignal`\\n- **Required:** no\\n\\nAborts the history read.\\n\\n```ts\\nconst result = await getTransactionHistory({\\n  signal, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await getTransactionHistory({\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n- [`executeIntent`](/sdk/actions/planner/executeIntent) — Execute a handle returned by estimateIntent.\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/history/getTransactionHistory.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/history/getTransactionHistory.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/history/getTransactionHistory.md","rawMarkdownTitle":"getTransactionHistory","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/history/getTransactionHistory.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"history","action":"getTransactionHistory"},"relativePath":"sdk/actions/history/getTransactionHistory.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),e={name:"sdk/actions/history/getTransactionHistory.md"};function r(o,s,l,h,c,p){return t(),i("div",null,[...s[0]||(s[0]=[n("",46)])])}const g=a(e,[["render",r]]);export{k as __pageData,g as default};
